 private void drawObject(Canvas c,WorldObject o,float x){if("lake_tree_03".equals(o.id)){drawVeilroot(c,o,x);return;}if("herb".equals(o.type)){drawHerb(c,o,x);return;}if("creature".equals(o.type)&&!(state.reedling!=null&&o.id.equals(state.reedling.objectId))){drawFantasyCreature(c,o,x);return;}String key=o.assetRef;if("creature".equals(o.type)){String a=state.reedling.activity==null?"idle":state.reedling.activity;key="reedling_"+(a.contains("forage")?"forage":a.contains("rest")?"rest":a.contains("flee")||a.contains("alert")?"alert":a.contains("wander")?"move":"idle");}Bitmap b=assets.get(key);if(b==null)return;float bob=0,scaleY=1;if("creature".equals(o.type)){double rhythm=state.reedling!=null&&state.reedling.body!=null?state.reedling.body.rhythm:.4,alert=state.reedling!=null&&state.reedling.sense!=null?state.reedling.sense.alertness:.2,strain=state.reedling!=null&&state.reedling.body!=null?state.reedling.body.strain:0;bob=(float)Math.sin(anim*(1.4+rhythm*3.2))*((float)(1.5+rhythm*2.8));bob+=(float)Math.sin(anim*9.0)*((float)(alert*1.2));scaleY=(float)(1-.05*strain+.025*Math.sin(anim*(1.2+rhythm*2.0)));}if("creature".equals(o.type)&&b.getWidth()>=8){int fw=b.getWidth()/8,fr=((int)(anim*(3.5+(state.reedling!=null&&state.reedling.body!=null?state.reedling.body.rhythm*4:1))))%8;float hh=o.height*scaleY;c.drawBitmap(b,new Rect(fr*fw,0,(fr+1)*fw,b.getHeight()),new RectF(x-o.width*.5f,o.y-hh+bob,x+o.width*.5f,o.y+bob),p);}else if(LivingWorldEngine.isLivingFlora(o)){FloraLifeState lf=LivingWorldEngine.flora(state,o.id);float angle=lf==null?0:(float)Math.sin(anim*(.42+lf.body.rhythm*1.1)+(o.id.hashCode()&31))*(float)(.25+lf.swayDrive*1.8);c.save();c.rotate(angle,x,o.y);c.drawBitmap(b,null,new RectF(x-o.width*.5f,o.y-o.height+bob,x+o.width*.5f,o.y+bob),p);c.restore();}else c.drawBitmap(b,null,new RectF(x-o.width*.5f,o.y-o.height+bob,x+o.width*.5f,o.y+bob),p);}
 private void drawVeilroot(Canvas c,WorldObject o,float x){FloraLifeState f=LivingWorldEngine.flora(state,o.id);String phase=f==null||f.cycle==null?"QUIET":f.cycle.phase;float cycleOpen="WEAK".equals(phase)?.48f:"RECOVER".equals(phase)?.70f:"GROW".equals(phase)?1.08f:1f,cycleMotion="WEAK".equals(phase)?.30f:"RECOVER".equals(phase)?.52f:1f;float y=o.y,open=(f==null?.6f:(float)(.35+.65*f.opening))*cycleOpen,sway=(f==null?0:(float)Math.sin(anim*(.38+f.body.rhythm*1.3)+(o.id.hashCode()&31))*(float)(4+14*f.swayDrive))*cycleMotion,pulse=f==null?0:(float)(.5+.5*Math.sin(anim*(.7+f.growthPulse*1.8)));p.setShader(null);p.setAntiAlias(false);p.setStrokeWidth(8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStyle(Paint.Style.STROKE);p.setColor(Color.rgb(70,86,83));Path trunk=new Path();trunk.moveTo(x,y);trunk.cubicTo(x-18,y-95,x+24+sway*.35f,y-190,x+sway,y-278);c.drawPath(trunk,p);p.setStrokeWidth(5f);for(int i=-2;i<=2;i++){float by=y-120-i*28,dir=i%2==0?-1:1,len=(42+Math.abs(i)*8)*open;Path arm=new Path();arm.moveTo(x+sway*.32f,by);arm.cubicTo(x+dir*18,by-8,x+dir*len*.72f+sway,by-28,x+dir*len+sway,by-42);p.setColor(Color.rgb(76,101,91));c.drawPath(arm,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.argb((int)(145+70*pulse),119,142,124));float px=x+dir*len+sway,py=by-42;c.drawOval(px-11*open,py-22*open,px+11*open,py+22*open,p);p.setStyle(Paint.Style.STROKE);}p.setStyle(Paint.Style.FILL);p.setColor(Color.argb((int)(80+120*pulse),188,115,144));for(int i=0;i<5;i++){float yy=y-78-i*42,xx=x+(float)Math.sin(i*1.7)*7+sway*(i/5f);c.drawCircle(xx,yy,2.2f+(f==null?0:(float)f.sense.moistureSense*1.8f),p);}p.setStyle(Paint.Style.FILL);p.setStrokeCap(Paint.Cap.BUTT);}
 private void drawFantasyCreature(Canvas c,WorldObject o,float x){CreatureLifeState s=LivingWorldEngine.creature(state,o.id);if(s==null)return;String phase=s.cycle==null?"ACTIVE":s.cycle.phase;float phaseMotion="WEAK".equals(phase)?.18f:"RECOVER".equals(phase)?.34f:"REST".equals(phase)?.28f:"GROW".equals(phase)?.72f:1f;float y=o.y,breathe=(float)Math.sin(anim*(1.2+s.body.rhythm*2.8)+(o.id.hashCode()&31))*(float)(1.2+s.body.rhythm*2.2)*phaseMotion,alert=(float)s.sense.alertness; p.setShader(null);p.setAntiAlias(false);if(o.id.startsWith("driftwing")){float lift=(float)Math.sin(anim*(1.1+s.locomotionDrive*2.4))*10f*phaseMotion;float spread=(18f+(float)s.sense.lumenSense*8f)*(.72f+.28f*phaseMotion);p.setColor(Color.argb(210,145,182,194));Path q=new Path();q.moveTo(x-spread,y-18+lift);q.quadTo(x,y-36-breathe+lift,x+spread,y-18+lift);q.quadTo(x,y-5+lift,x-spread,y-18+lift);q.close();c.drawPath(q,p);p.setColor(Color.argb(180,206,229,222));c.drawRect(x-2,y-24+lift,x+2,y-10+lift,p);}else{float crouch=(float)(s.body.strain*5+s.avoidance*3)+(1-phaseMotion)*5f,w=(22f+(float)s.body.structure*8f)*(.82f+.18f*phaseMotion);p.setColor(Color.rgb(88,112,94));c.drawOval(x-w,y-24+crouch+breathe,x+w,y+crouch,p);p.setColor(Color.rgb(134,157,126));for(int i=-2;i<=2;i++){float px=x+i*8;c.drawRect(px-2,y-34+crouch-alert*7,px+2,y-18+crouch,p);}p.setColor(Color.rgb(178,199,153));c.drawRect(x-3,y-22+crouch,x+3,y-16+crouch,p);} }
 private void drawHerb(Canvas c,WorldObject o,float x){HerbDefinition d=HerbalismEngine.definition(o);if(d==null)return;FloraLifeState f=LivingWorldEngine.flora(state,o.id);String phase=f==null||f.cycle==null?"QUIET":f.cycle.phase;float cycleOpen="WEAK".equals(phase)?.46f:"RECOVER".equals(phase)?.68f:"GROW".equals(phase)?1.08f:1f;float cycleMotion="WEAK".equals(phase)?.35f:"RECOVER".equals(phase)?.52f:1f;float y=o.y,sw=f==null?0:(float)Math.sin(anim*(.8+f.body.rhythm*2.2)+(o.id.hashCode()&31))*(float)(2+9*f.swayDrive)*cycleMotion,open=(f==null?1:(float)(.55+.45*f.opening))*cycleOpen;p.setShader(null);p.setAntiAlias(false);if("mistleaf".equals(d.id)){p.setColor(Color.rgb(134,157,132));for(int i=-2;i<=2;i++){float dx=i*7,tip=sw*(1-Math.abs(i)*.12f);c.drawRect(x+dx-2,y-13,x+dx+2,y,p);c.drawRect(x+dx+tip-2,y-25-Math.abs(i)*2,x+dx+tip+2,y-12,p);c.drawRect(x+dx+tip-7*open,y-23-Math.abs(i)*2,x+dx+tip+7*open,y-17-Math.abs(i)*2,p);}}else if("blue_reed".equals(d.id)){p.setColor(Color.rgb(78,125,110));for(int i=-2;i<=2;i++){float dx=i*8,h=48+Math.abs(i%2)*13,tip=sw*(.65f+Math.abs(i)*.08f);c.drawRect(x+dx-1,y-h*.52f,x+dx+2,y,p);c.drawRect(x+dx+tip-1,y-h,x+dx+tip+2,y-h*.48f,p);p.setColor(Color.rgb(98,143,154));c.drawRect(x+dx+tip-2,y-h-7,x+dx+tip+3,y-h,p);p.setColor(Color.rgb(78,125,110));}}else{p.setColor(Color.rgb(91,108,76));c.drawOval(x-30*open+sw*.2f,y-10,x+30*open+sw*.2f,y+2,p);p.setColor(Color.rgb(184,104,118));for(int i=0;i<5;i++)c.drawRect(x-22+i*10+sw*.4f,y-14-(i%2)*3,x-18+i*10+sw*.4f,y-10-(i%2)*3,p);}}
 private void drawGirl(Canvas c,float x,float ground){if(x<-240||x>2640)return;float lift=state.girlPhysics==null?0:(float)WorldUnits.mToPx(Math.max(0,state.girlPhysics.groundClearanceM)),bodyGround=ground-lift;GirlAnimationController.Visual v=GirlAnimationController.select(state);Bitmap b=assets.get(v.asset);if(b==null){p.setColor(Color.argb(46,0,0,0));c.drawOval(x-47,ground-8,x+47,ground+10,p);BlockBodyRenderer.drawHuman(c,p,state,x,bodyGround);return;}int frame=v.isWalk()&&state.bodyRig!=null?Math.min(v.frames-1,(int)Math.floor(state.bodyRig.stridePhase*v.frames)%v.frames):Math.min(v.frames-1,(int)(anim*v.fps)%v.frames),fw=b.getWidth()/v.frames,fh=b.getHeight();float sc=1.34f,ax=v.anchorX*fw*sc;float left=x-ax,top=GirlAnimationController.renderTop(bodyGround,fh,sc,v.anchorY);BodyRigState rig=state.bodyRig;if(rig!=null){float lean=(float)(rig.spineLean*22.0+rig.pelvisTilt*10.0);left+=lean;}BodyInstinctState bi=state.bodyInstinct;if(bi!=null){float breath=(float)(Math.sin(anim*(2.0+bi.breathDrive*2.4))*bi.breathDrive*2.2);float shiver=(float)(Math.sin(anim*24)*bi.shiver*1.7);float droop=(float)(bi.fatigueDroop*5.0);left+=shiver;top+=droop+breath;}int shadowAlpha=(int)Math.max(18,58-Math.min(38,lift*.35f));float shadowScale=Math.max(.55f,1-lift/260f);p.setColor(Color.argb(v.state==GirlAnimationController.State.SIT?Math.min(44,shadowAlpha):shadowAlpha,0,0,0));c.drawOval(x-47*shadowScale,ground-8,x+47*shadowScale,ground+10,p);p.setAlpha((int)(190+65*state.environment.ambientBrightness));c.drawBitmap(b,new Rect(frame*fw,0,(frame+1)*fw,fh),new RectF(left,top,left+fw*sc,top+fh*sc),p);p.setAlpha(255);}
 private void drawWeather(Canvas c,float cam){if(!"RAIN".equals(state.environment.weather))return;Bitmap rain=assets.get("rain_layer_2");if(rain!=null){c.save();WorldObject shelter=state.world.object("shelter_01");WorldArea ca=state.world.areaAt(state.catX);if(shelter!=null&&ca!=null&&"home_shelter".equals(ca.id)){float sx=shelter.x-cam;c.clipOutRect(sx-shelter.width*.5f,shelter.y-shelter.height,sx+shelter.width*.5f,shelter.y);}Bitmap far=assets.get("rain_layer_0"),mid=assets.get("rain_layer_1");float yf=(anim*95)%1080,ym=(anim*140)%1080;if(far!=null){p.setAlpha(70);c.drawBitmap(far,null,new RectF(0,yf-1080,2400,yf),p);c.drawBitmap(far,null,new RectF(0,yf,2400,yf+1080),p);}if(mid!=null){p.setAlpha(110);c.drawBitmap(mid,null,new RectF(0,ym-1080,2400,ym),p);c.drawBitmap(mid,null,new RectF(0,ym,2400,ym+1080),p);}p.setAlpha((int)(90+120*state.environment.weatherIntensity));float y=(anim*190)%1080;c.drawBitmap(rain,null,new RectF(0,y-1080,2400,y),p);c.drawBitmap(rain,null,new RectF(0,y,2400,y+1080),p);p.setAlpha(255);c.restore();}}
 private ColorFilter worldPaletteFilter(){float saturation=1.20f,contrast=1.08f,offset=128f*(1f-contrast);ColorMatrix sat=new ColorMatrix();sat.setSaturation(saturation);ColorMatrix con=new ColorMatrix(new float[]{contrast,0,0,0,offset,0,contrast,0,0,offset,0,0,contrast,0,offset,0,0,0,1,0});sat.postConcat(con);return new ColorMatrixColorFilter(sat);}
